// Combined curved/graded source Race movement on authored wide roads.
#include "race.hpp"
#include "assets.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)return 2;rr::Assets a(argv[1]);auto specs=rr::read_bike_specs(a.read("DATA/BIKESPEC.RSC"));auto t=rr::read_physics_tables(a.read("ROADRASH.EXE"));bool first=true;std::cout<<"[";for(size_t id=0;id<specs.size();++id)for(int scenario=0;scenario<3;++scenario){rr::RouteSample sample{{0,0,50000,50000,512,512},0,0,0};sample.path.shoulder_left=sample.path.shoulder_right=250;std::vector<rr::RouteSample> route(20000,sample);for(size_t i=0;i<route.size();++i){route[i].path.bend=scenario==0?0:((i/30)%2?4:-4);route[i].path.rise=scenario==2?((i/30)%2?10:-10):0;}rr::Race race(route,route,t,specs[id],75);auto& b=race.riders()[0].bike;b.i32(0x160)=74;b.i32(0xec)=8000;b.i32(0x28)=0;for(int tick=0;tick<600;++tick){race.step(rr::control_accelerate);if(!first){std::cout<<",";}first=false;std::cout<<"["<<id+1<<","<<scenario<<","<<tick+1<<","<<b.i32(0xec)<<","<<b.i32(0x1c)-12800<<","<<b.i32(0x28)<<","<<b.i32(0x160)<<","<<b.i32(0x20)<<","<<b.i32(0xf4)<<","<<b.i32(0x11c)<<","<<b.i32(0xfc)<<"]";}}std::cout<<"]\n";}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
